#include <array>
#include <cstdint>

std::array<std::uint8_t, 4> toLittleEndian(std::uint32_t value)
{
    std::array<std::uint8_t, 4> bytes{};
    for (int i{ 0 }; i < 4; ++i)
        bytes[i] = static_cast<std::uint8_t>((value >> (8 * i)) & 0xFF);
    return bytes;
}

std::uint32_t fromLittleEndian(const std::array<std::uint8_t, 4>& bytes)
{
    std::uint32_t value{ 0 };
    for (int i{ 0 }; i < 4; ++i)
        value |= static_cast<std::uint32_t>(bytes[i]) << (8 * i);
    return value;
}

unitTests:
using Bytes = std::array<std::uint8_t, 4>;
TEST("splitting into bytes") {
    CHECK(toLittleEndian(0x12345678u) == (Bytes{ 0x78, 0x56, 0x34, 0x12 }));
    CHECK(toLittleEndian(1u) == (Bytes{ 1, 0, 0, 0 }));
    CHECK(toLittleEndian(0xFF000000u) == (Bytes{ 0, 0, 0, 0xFF }));
    CHECK(toLittleEndian(0u) == (Bytes{ 0, 0, 0, 0 }));
}
TEST("joining bytes") {
    CHECK_EQ(fromLittleEndian(Bytes{ 0x78, 0x56, 0x34, 0x12 }), 0x12345678u);
    CHECK_EQ(fromLittleEndian(Bytes{ 0xEF, 0xBE, 0xAD, 0xDE }), 0xDEADBEEFu);
    CHECK_EQ(fromLittleEndian(Bytes{ 0x2A, 0, 0, 0 }), 42u);
}
TEST("round trips") {
    for (std::uint32_t x : { 0u, 1u, 255u, 256u, 65535u, 0x80000000u, 0xFFFFFFFFu, 0x0BADF00Du })
        CHECK_EQ(fromLittleEndian(toLittleEndian(x)), x);
}

